//! A chunk checked against its sidecar, this build's constants and the rules: every game replayed
//! move by move to the ending it names, and a sample regenerated byte for byte.

use std::path::{Path, PathBuf};

use cadence_dataset::chunk::Header;

use crate::tt::Table;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Summary {
    pub name: String,
    pub sha256: String,
    pub header: Header,
    pub games: u64,
    pub plies: u64,
    pub kinds: [u64; 2],
    pub endings: [[u64; 5]; 2],
    pub outcomes: [[u64; 3]; 2],
    pub phase: Vec<u64>,
    pub balance: Vec<u64>,
    pub replayed: u64,
}

